const listUserTickets = `-- name: ListUserTickets :many
SELECT
    t.id,
    t.order_id,
    t.event_id,
    t.seat_id,
    t.user_id,
    t.ticket_code,
    t.status,
    t.issued_at,
    o.order_code,
    o.payment_method,
    o.paid_at,
    oi.price AS seat_price,
    e.name AS event_name,
    e.slug AS event_slug,
    e.starts_at AS event_starts_at,
    e.city AS event_city,
    e.image_url AS event_image_url,
    v.name AS venue_name,
    v.address AS venue_address,
    s.seat_label,
    s.row_label,
    s.seat_number,
    vz.id AS zone_id,
    vz.code AS zone_code,
    vz.name AS zone_name
FROM tickets t
JOIN orders o ON o.id = t.order_id
LEFT JOIN order_items oi ON oi.order_id = t.order_id AND oi.seat_id = t.seat_id
JOIN events e ON e.id = t.event_id
JOIN venues v ON v.id = e.venue_id
JOIN seats s ON s.id = t.seat_id
JOIN venue_zones vz ON vz.id = s.zone_id
WHERE t.user_id = $1
  AND t.status <> 'VOID'
ORDER BY t.issued_at DESC, s.seat_label ASC
`

