const markAvailableSeatSold = `-- name: MarkAvailableSeatSold :execrows
UPDATE event_seats
SET status = 'SOLD',
    version = version + 1,
    updated_at = now()
WHERE event_id = $1
  AND seat_id = $2
  AND status = 'AVAILABLE'
`

type MarkAvailableSeatSoldParams struct {
	EventID pgtype.UUID `json:"event_id"`
	SeatID  pgtype.UUID `json:"seat_id"`
}

func (q *Queries) MarkAvailableSeatSold(ctx context.Context, arg MarkAvailableSeatSoldParams) (int64, error) {
	result, err := q.db.Exec(ctx, markAvailableSeatSold, arg.EventID, arg.SeatID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

